    {(section==='orders'||section==='home')&&<><div className=\"overview-header\"><span className=\"overview-label\">Обзор заказов</span><DropdownMenu renderSwitcher={props=><Button {...props} view=\"flat\" size=\"s\"><Icon data={Calendar} size={14}/>{dateFilter==='today'?'20 мая 2025':dateFilter==='recent'?'18–20 мая 2025':'14–20 мая 2025'}<Icon data={ChevronDown} size={12}/></Button>} items={[{text:'Последние 7 дней',action:()=>setDateFilter('all')},{text:'Последние 3 дня',action:()=>setDateFilter('recent')},{text:'Сегодня',action:()=>setDateFilter('today')}]}/></div><StatCards orders={orders.filter(o=>dateFilter==='all'||(dateFilter==='today'?o.date==='20 мая 2025':Number(o.date.split(' ')[0])>=18))}/>{tablePanel}<div className=\"table-tip\"><Icon data={LayoutColumns3} size={14}/><span>Настройте таблицу под себя: перетаскивайте заголовки, чтобы изменить порядок колонок.</span><span className=\"tip-key\">Drag & drop</span></div></>}
    {section==='users'&&<section className=\"users-panel\"><div className=\"section-toolbar\"><Text variant=\"subheader-3\">Клиенты магазина</Text><TextInput size=\"l\" placeholder=\"Найти клиента\" value={query} onUpdate={setQuery} startContent={<Icon data={Magnifier} size={16}/>} hasClear/></div><div className=\"users-grid\">{orders.filter((o,i,a)=>a.findIndex(x=>x.email===o.email)===i).filter(o=>"'`${o.name} ${o.email}`.toLowerCase().includes(query.toLowerCase())).map(o=><div className="user-card" key={o.email}><Customer order={o}/><div><span className="muted">Заказы</span><strong>{orders.filter(x=>x.email===o.email).length}</strong></div><div><span className="muted">Сумма покупок</span><strong>{money(orders.filter(x=>x.email===o.email).reduce((s,x)=>s+x.amount,0))}</strong></div><Button view="outlined" onClick={()=>{setSection('"'orders');setQuery(o.email);setTab('all');}}>Посмотреть заказы<Icon data={ArrowRight} size={14}/></Button></div>)}</div></section>}
    {section==='settings'&&<section className=\"settings-panel\"><Text variant=\"subheader-3\">Общие настройки</Text><p className=\"muted\">Основная информация о вашем рабочем пространстве</p><label>Название магазина<TextInput size=\"l\" value={shopName} onUpdate={setShopName}/></label><label>Email администратора<TextInput size=\"l\" defaultValue=\"alexey@myshop.ru\" type=\"email\"/></label><div className=\"setting-switch\"><div><strong>Уведомления о заказах</strong><p className=\"muted\">Сообщать о новых заказах и изменениях статуса</p></div><Switch checked={notifications} onUpdate={setNotifications} aria-label=\"Уведомления о заказах\"/></div><div className=\"setting-switch\"><div><strong>Компактная навигация</strong><p className=\"muted\">Показывать только иконки разделов</p></div><Switch checked={compact} onUpdate={setCompact} aria-label=\"Компактная навигация\"/></div><Button view=\"action\" size=\"l\" onClick={()=>{localStorage.setItem('orbit-shop',JSON.stringify(shopName));setToast('Настройки сохранены');}}>Сохранить изменения</Button></section>}
    <footer className=\"page-footer\"><span>© 2025 Orbit. Всё под контролем.</span><span><span className=\"system-dot\"/>Все системы работают</span></footer></main></div>}/>
    <Modal open={Boolean(modal)} onClose={()=>setModal(null)} contentClassName=\"app-modal\"><div className=\"modal-heading\"><Text variant=\"header-1\">{({create:'Новый заказ',filters:'Фильтры заказов',columns:'Настройка колонок',help:'Центр помощи',workspace:'Рабочее пространство'} as Record<string,string>)[modal||'']}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={()=>setModal(null)}><Icon data={Xmark} size={18}/></Button></div>
    {modal==='create'&&<form className=\"modal-form\" onSubmit={createOrder}><p className=\"muted\">Добавьте заказ — он появится в группе «В обработке».</p><label>Имя клиента<TextInput size=\"l\" value={newName} onUpdate={setNewName} placeholder=\"Иван Иванов\" autoFocus/></label><label>Email<TextInput size=\"l\" type=\"email\" value={newEmail} onUpdate={setNewEmail} placeholder=\"client@example.com\"/></label><label>Сумма заказа, ₽<TextInput size=\"l\" type=\"number\" value={newAmount} onUpdate={setNewAmount} placeholder=\"0\" controlProps={{min:1,step:0.01}}/></label>{formError&&<span className=\"form-error\">{formError}</span>}<div className=\"modal-actions\"><Button view=\"outlined\" onClick={()=>setModal(null)}>Отмена</Button><Button view=\"action\" type=\"submit\">Создать заказ</Button></div></form>}
    {modal==='filters'&&<div className=\"modal-form\"><label>Статус заказа<Select size=\"l\" width=\"max\" value={[tab]} onUpdate={v=>setTab(v[0])} options={[{value:'all',content:'Все статусы'},...statuses.map(s=>({value:s.id,content:s.label}))]}/></label><label>Оплата<Select size=\"l\" width=\"max\" value={[payFilter]} onUpdate={v=>setPayFilter(v[0])} options={[{value:'all',content:'Любая оплата'},{value:'paid',content:'Оплачено'},{value:'unpaid',content:'Ожидает оплаты'}]}/></label><label>Период<Select size=\"l\" width=\"max\" value={[dateFilter]} onUpdate={v=>setDateFilter(v[0])} options={[{value:'all',content:'Последние 7 дней'},{value:'recent',content:'Последние 3 дня'},{value:'today',content:'Сегодня'}]}/></label><div className=\"modal-actions\"><Button view=\"outlined\" onClick={()=>{setTab('all');setPayFilter('all');setDateFilter('all');}}>Сбросить</Button><Button view=\"action\" onClick={()=>setModal(null)}>Показать заказы</Button></div></div>}
    {modal==='columns'&&<div className=\"modal-form\"><p className=\"muted\">Выберите видимые колонки. Меняйте порядок стрелками или перетаскивайте заголовки в таблице.</p>{columnOrder.filter(id=>columnNames[id]).map((id,i,a)=><div key={id} className=\"column-setting\"><Checkbox checked={columnVisibility[id]"'!==false} onUpdate={v=>setColumnVisibility(prev=>({...prev,[id]:v}))}>{columnNames[id]}</Checkbox><div><Button size="s" view="flat" disabled={i===0} aria-label={`Переместить ${columnNames[id]} влево`} onClick={()=>{const next=[...columnOrder];const idx=next.indexOf(id);[next[idx-1],next[idx]]=[next[idx],next[idx-1]];setColumnOrder(next);}}><Icon data={ChevronLeft} size={14}/></Button><Button size="s" view="flat" disabled={i===a.length-1} aria-label={`Переместить ${columnNames[id]} вправо`} onClick={()=>{const next=[...columnOrder];const idx=next.indexOf(id);[next[idx+1],next[idx]]=[next[idx],next[idx+1]];setColumnOrder(next);}}><Icon data={ChevronRight} size={14}/></Button></div></div>)}<div className="modal-actions"><Button view="outlined" onClick={()=>{setColumnOrder(['"'select','id','customer','date','amount','status','payment','actions']);setColumnVisibility({});}}>По умолчанию</Button><Button view=\"action\" onClick={()=>setModal(null)}>Готово</Button></div></div>}
    {modal==='help'&&<div className=\"help-content\"><p className=\"muted\">Несколько подсказок для удобной работы с Orbit.</p>{[['Как изменить порядок колонок?','Зажмите заголовок колонки и перетащите его в нужное место. Порядок сохранится автоматически.'],['Как работать с группами?','Нажмите «По статусу», чтобы включить группировку. Стрелка рядом со статусом сворачивает группу.'],['Как обновить несколько заказов?','Выделите заказы галочками и выберите новый статус на появившейся панели.'],['Как выгрузить заказы?','Нажмите «Экспорт». Если есть выделенные заказы, в CSV попадут только они.']].map(([q,a])=><div key={q}><strong>{q}</strong><p className=\"muted\">{a}</p></div>)}</div>}
    {modal==='workspace'&&<div className=\"modal-form\"><div className=\"workspace-preview\"><span className=\"shop-monogram\">М</span><div><Text variant=\"subheader-2\">{shopName}</Text><p className=\"muted\">Ваше рабочее пространство · Тариф Pro</p></div><Icon data={Check} size={18}/></div><p className=\"muted\">Администратор: Алексей Ким<br/>{orders.length} заказов · {new Set(orders.map(o=>o.email)).size} клиентов</p><Button view=\"action\" onClick={()=>{setModal(null);setSection('settings');}}>Настройки магазина</Button></div>}
    </Modal>
    <Modal open={Boolean(detail)} onClose={()=>setDetail(null)} contentClassName=\"app-modal\"><div className=\"modal-heading\"><Text variant=\"header-1\">Заказ #{detail?.id}</Text><Button view=\"flat\" aria-label=\"Закрыть заказ\" onClick={()=>setDetail(null)}><Icon data={Xmark} size={18}/></Button></div>{detail&&<div className=\"modal-form\"><Customer order={detail}/><div className=\"detail-row\"><span className=\"muted\">Создан</span><span>{detail.date}, {detail.time}</span></div><div className=\"detail-row\"><span className=\"muted\">Товар</span><span>{detail.product}</span></div><div className=\"detail-row\"><span className=\"muted\">Количество товаров</span><span>{detail.items}</span></div><div className=\"detail-row\"><span className=\"muted\">Сумма</span><strong>{money(detail.amount)}</strong></div><label>Статус<Select size=\"l\" width=\"max\" value={[detail.status]} onUpdate={v=>{changeStatus([detail.id],v[0] as Status);setDetail({...detail,status:v[0] as Status});}} options={statuses.map(s=>({value:s.id,content:s.label}))}/></label><Checkbox checked={detail.paid} onUpdate={paid=>{setDetail({...detail,paid});setOrders(prev=>prev.map(o=>o.id===detail.id?{...o,paid}:o));}}>Заказ оплачен</Checkbox><div className=\"modal-actions\"><Button view=\"action\" onClick={()=>setDetail(null)}>Готово</Button></div></div>}</Modal>
    {toast&&<div className=\"toast\" role=\"status\"><span className=\"toast-check\"><Icon data={Check} size={17}/></span>{toast}<Button view=\"flat\" size=\"s\" aria-label=\"Скрыть уведомление\" onClick={()=>setToast('')}><Icon data={Xmark} size={14}/></Button></div>}
  </>;
}
EOF"

/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root_theme_light {
