.sidebar-footer {padding:var(--g-spacing-4);}
.support-card {padding:var(--g-spacing-4);display:flex;flex-direction:column;gap:var(--g-spacing-2);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);margin-bottom:var(--g-spacing-5);}
