.support-card>.muted {font-size:10px;white-space:nowrap;}
.support-icon {color:var(--g-color-text-secondary);margin-bottom:var(--g-spacing-1);}
.support-card .g-button {margin-top:var(--g-spacing-2);font-size:11px;}
.sidebar-help {color:var(--g-color-text-secondary);font-size:12px;}
.profile {display:flex;align-items:center;gap:var(--g-spacing-2);margin-top:var(--g-spacing-5);padding-top:var(--g-spacing-4);border-top:1px solid var(--g-color-line-generic);}
