    it("'`renders navigation, grouped orders and controls in ${theme} theme`, () => {
      const markup = renderToStaticMarkup(<ThemeProvider theme={theme}><App /></ThemeProvider>);
      for (const label of ['"'Главная', 'Пользователи', 'Заказы', 'Настройки', 'Анна Смирнова', '#1048', 'В обработке', 'В доставке', 'Выполнен', 'Создать заказ', 'Настроить колонки', 'Следующая страница']) {
